use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    next_ticket: usize,
    serving: usize,
}

struct Semaphore {
    state: Mutex<State>,
    changed: Condvar,
}

impl Semaphore {
    fn new() -> Self {
        Self {
            state: Mutex::new(State {
                next_ticket: 0,
                serving: 0,
            }),
            changed: Condvar::new(),
        }
    }

    fn acquire(&self) -> Permit<'_> {
        let mut state = self.state.lock().unwrap();
        let ticket = state.next_ticket;
        state.next_ticket += 1;

        while state.serving != ticket {
            state = self.changed.wait(state).unwrap();
        }

        Permit { s: self }
    }
}

struct Permit<'a> {
    s: &'a Semaphore,
}

impl Drop for Permit<'_> {
    fn drop(&mut self) {
        let mut state = self.s.state.lock().unwrap();
        state.serving += 1;
        self.s.changed.notify_all();
    }
}

fn activate(s: Arc<Semaphore>) {
    let _permit = s.acquire();
    std::hint::black_box(());
}

fn run_role(s: Arc<Semaphore>) {
    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let activation1 = thread::spawn(move || activate(s1));
    let activation2 = thread::spawn(move || activate(s2));

    activation1.join().unwrap();
    activation2.join().unwrap();
}

fn w1(s: Arc<Semaphore>) {
    run_role(s);
}

fn w2(s: Arc<Semaphore>) {
    run_role(s);
}

fn w3(s: Arc<Semaphore>) {
    run_role(s);
}

fn main() {
    let s = Arc::new(Semaphore::new());

    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);
    let s3 = Arc::clone(&s);

    let worker1 = thread::spawn(move || w1(s1));
    let worker2 = thread::spawn(move || w2(s2));
    let worker3 = thread::spawn(move || w3(s3));

    worker1.join().unwrap();
    worker2.join().unwrap();
    worker3.join().unwrap();

    println!("DONE done=1");
}
